import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css"; 
import { ShoppingCart } from "lucide-react";

export default function Navbar({ setActiveSection }) {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <nav className="custom-navbar">
      <div className="nav-brand">✺ Sinthu</div>

      <div className="hamburger" onClick={() => setMenuOpen(!menuOpen)}>
        ☰
      </div>

      <ul className={`nav-links ${menuOpen ? "open" : ""}`}>
        <li onClick={() => setActiveSection("home")}><a href="#">Home</a></li>
        <li onClick={() => setActiveSection("products")}><a href="#">Products</a></li>
        <li onClick={() => setActiveSection("assurance")}><a href="#">Contact Us</a></li>
        <li><a href="#">Login</a></li>
        <li>
          <a href="#">
            <ShoppingCart size={20} />
          </a>
        </li>
      </ul>
    </nav>
  );
}
